@namespace sv_62edac3ce0ae4c9982fb7dd490903ca4.Components.Pages.Catalog

<div class="catalog-toolbar" style="display:flex;align-items:center;justify-content:space-between;padding:0.75rem 0;border-bottom:1px solid #eee;margin-bottom:1rem;">
    <div>
        <label for="sort-select" style="margin-right:0.5rem;font-weight:bold;">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged" style="padding:0.4rem;border:1px solid #ccc;border-radius:4px;">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <span style="color:#666;">
        @if (TotalCount > 0)
        {
            @($"Showing {StartItem}–{EndItem} of {TotalCount} products")
        }
        else
        {
            @("No products found")
        }
    </span>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private int StartItem => TotalCount == 0 ? 0 : (Page - 1) * PageSize + 1;
    private int EndItem => Math.Min(Page * PageSize, TotalCount);

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_62edac3ce0ae4c9982fb7dd490903ca4.Components.Pages.Catalog

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" style="display:flex;align-items:center;justify-content:center;gap:0.5rem;padding:1rem 0;">
        <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
            style="padding:0.4rem 0.8rem;border:1px solid #ccc;border-radius:4px;cursor:pointer;">
            Previous
        </button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var pageNum = i;
            <button @onclick="() => GoToPage(pageNum)"
                style="padding:0.4rem 0.8rem;border:1px solid #ccc;border-radius:4px;cursor:pointer;@(pageNum == CurrentPage ? "background:#0d6efd;color:white;border-color:#0d6efd;" : "")">
                @pageNum
            </button>
        }

        <button disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
            style="padding:0.4rem 0.8rem;border:1px solid #ccc;border-radius:4px;cursor:pointer;">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

@page "/catalog"
@namespace sv_62edac3ce0ae4c9982fb7dd490903ca4.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-page" style="display:flex;gap:1.5rem;padding:1rem;">
    @* Left sidebar *@
    <aside style="flex:0 0 25%;min-width:220px;">
        @if (_categoriesLoaded)
        {
            <CatalogFilters Categories="_categories" OnFilterApplied="HandleFilterApplied" OnFilterCleared="HandleFilterCleared" />
        }
    </aside>

    @* Main content *@
    <main style="flex:1;">
        @if (_error is not null)
        {
            <div class="error-state" style="padding:2rem;text-align:center;color:#dc3545;border:1px solid #dc3545;border-radius:8px;">
                <p>Something went wrong: @_error</p>
                <button @onclick="LoadProducts" style="padding:0.5rem 1rem;background:#0d6efd;color:white;border:none;border-radius:4px;cursor:pointer;">
                    Retry
                </button>
            </div>
        }
        else if (_loading)
        {
            <div class="loading-state" style="padding:2rem;text-align:center;color:#666;">
                <p>Loading products...</p>
            </div>
        }
        else if (_result is not null && _result.Items.Count == 0)
        {
            <div class="empty-state" style="padding:2rem;text-align:center;color:#666;">
                <p>No products match your filters.</p>
            </div>
        }
        else if (_result is not null)
        {
            <CatalogToolbar SortBy="@_sortBy" Page="_currentPage" PageSize="_pageSize" TotalCount="_result.TotalCount" OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="_result.Items" OnProductSelected="HandleProductSelected" OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="_currentPage" TotalPages="TotalPages" OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    /// <summary>
    /// Raised when a product card is clicked, allowing the parent layout or host to navigate to a detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> _categories = [];
    private bool _categoriesLoaded;
    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int _pageSize = 12;

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _pageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            _categories = [];
        }
        _categoriesLoaded = true;
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

